const list = document.getElementById("habits");
const status = document.getElementById("status");
let state = { data: { habits: [] }, revisions: { habits: {} } };
let today = "";
const dayBefore = (date, days = 1) => {
  const at = new Date(date + "T12:00:00Z");
  at.setUTCDate(at.getUTCDate() - days);
  return at.toISOString().slice(0, 10);
};
// Days in a row done, ending today; a habit not yet done today shows 0.
const streakOf = (habit) => {
  const done = new Set(habit.done);
  let count = 0;
  for (let day = today; done.has(day); day = dayBefore(day)) count += 1;
  return count;
};
const show = () => {
  list.replaceChildren(...state.data.habits.map((habit) => {
    const item = document.createElement("li");
    item.dataset.hook = "habit";
    const name = document.createElement("span");
    name.className = "name";
    name.textContent = habit.name;
    const streak = document.createElement("span");
    streak.className = "streak";
    streak.dataset.hook = "habit-streak";
    const days = streakOf(habit);
    streak.textContent = days + (days === 1 ? " day in a row" : " days in a row");
    const done = document.createElement("button");
    done.type = "button";
    done.dataset.hook = "habit-done";
    const doneToday = habit.done.includes(today);
    done.textContent = doneToday ? "Done today" : "Mark done today";
    done.setAttribute("aria-pressed", String(doneToday));
    done.addEventListener("click", () => markDone(habit));
    item.append(name, streak, done);
    return item;
  }));
};
const load = () =>
  tessera.call("clock.now").then((clock) => {
    today = clock.date;
    return tessera.call("data.read");
  }).then((read) => { state = read; show(); });
const save = (operations, said) =>
  tessera.call("data.patch", { operations }).then(load).then(
    () => { status.textContent = said; },
    () => { status.textContent = "That wasn't saved. Try again."; return load(); },
  );
const markDone = (habit) => {
  if (habit.done.includes(today)) return;
  save(
    [{ op: "replace", collection: "habits", id: habit.id, revisionCount: state.revisions.habits[habit.id], fields: { done: [...habit.done, today] } }],
    habit.name + " is done today.",
  );
};
const add = () => {
  const input = document.getElementById("name");
  const name = input.value.trim();
  if (!name) { status.textContent = "Write the habit's name first."; return; }
  input.value = "";
  save([{ op: "add", collection: "habits", record: { name, done: [] } }], name + " was added.");
};
document.querySelector("[data-hook=habit-add]").addEventListener("click", add);
document.getElementById("name").addEventListener("keydown", (event) => {
  if (event.key === "Enter") add();
});
load();

